namespace
{
	// The sinks of one line. queued: called by the writer thread of paris_console_writer.hpp, which keeps the console log open
	// (flushed after each batch) and skips the rcon check the printing thread already made.
	void write_sinks(const int type, const std::string& message, const bool queued)
	{
		auto out = message;
		if (out.empty() || out.back() != '\n')
		{
			out.push_back('\n');
		}

		if (console_log && console_log->current.string)
		{
			if (!queued || !paris_console_writer::console_log_stream().append(console_log->current.string, out))
				utils::io::write_file(console_log->current.string, out, true);
		}

		if (console::is_enabled())
		{
			if (wincon::is_enabled())
			{
				printf(message.data());
			}
			else if (terminal::is_enabled())
			{
				if (queued)
				{
					::terminal::dispatch_message_direct(type, message);
				}
				else
				{
					::terminal::dispatch_message(type, message);
				}
				return;
			}
			else if (syscon::is_enabled())
			{
				::syscon::Sys_Print(message.data());
			}
		}

		game_console::print(type, message);
	}
}

void dispatch_message_queued(const int type, const std::string& message)
{
	write_sinks(type, message, true);
}

void dispatch_message(const int type, const std::string& message)
{
	if (rcon::message_redirect(message))
	{
		return;
	}

	// A dedicated server hands the line to the writer thread; the syscon window belongs to this thread and stays synchronous.
	if (!syscon::is_enabled() && paris_console_writer::submit(type, message))
	{
		return;
	}

	write_sinks(type, message, false);
}

